				retained.add(capture(source, layout, materializer, coordinates, new long[] { 42L, 50L }, 0L, 0L));
				retained.add(capture(source, layout, materializer, coordinates, new long[] { 42L, 50L }, 0L, 1L));
				retained.add(capture(source, layout, materializer, coordinates, new long[] { 42L, 51L }, 0L, 2L));
				// A rejected producer row must not be needed to publish the second accepted A coordinate.
				prepare(source, layout, materializer, coordinates, new long[] { 42L, 50L }, 0L, 0L);
				retained.add(capture(source, layout, materializer, coordinates, new long[] { 42L, 50L }, 0L, 1L));
