	@Test
	void omissionPreservesOrdinaryReuseAndFallsBackAfterUnboundAndViewChanges() {
		System.setProperty(PROPERTY, "value");
		NativeProjectedBindingSet.ProjectionLayout layout = layout("value");
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		CountingSource source = source(42L);
		Coordinates coordinates = new Coordinates(1);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			try (NativeResultMaterializer materializer = plan.open(ledger)) {
				NativeProjectedBindingSet first = capture(source, layout, materializer, coordinates,
						new long[] { 42L }, 0L);
				NativeProjectedBindingSet repeated = capture(source, layout, materializer, coordinates,
						new long[] { 42L }, 1L);
				assertThat(repeated.getValue("value")).isSameAs(first.getValue("value"));
				assertThat(source.calls).containsExactly(42L);
				NativeProjectedBindingSet unbound = capture(source, layout, materializer, coordinates,
						new long[] { NativeLmdbQuerySource.UNKNOWN_ID }, 2L);
				assertThat(unbound.hasBinding("value")).isFalse();
				capture(source, layout, materializer, coordinates, new long[] { 42L }, 0L);
				assertThat(source.calls).containsExactly(42L, 42L);
				Value replacement = VF.createBNode("replacement-42");
				source.values.put(42L, replacement);
				source.scope = new Object();
				NativeProjectedBindingSet changed = capture(source, layout, materializer, coordinates,
						new long[] { 42L }, 0L);
				assertThat(changed.getValue("value")).isSameAs(replacement);
				assertThat(first.getValue("value").stringValue()).isEqualTo("value-42");
				assertThat(source.calls).containsExactly(42L, 42L, 42L);
				assertThat(ledger.usedBytes()).isEqualTo(materializer.retainedBytes());
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

