	@Test
	void canonicalExclusionCoversAliasesBeyondOneLongMaskWord() {
		String[] names = new String[65];
		int[] slots = new int[65];
		int[] masks = new int[65];
		for (int index = 0; index < names.length; index++) {
			names[index] = "value" + index;
			slots[index] = index == 64 ? 0 : index;
			masks[index] = ValuePosition.OBJECT;
		}
		System.setProperty(PROPERTY, "value0");
		NativeProjectedBindingSet.ProjectionLayout layout = NativeProjectedBindingSet.ProjectionLayout.create(
				names, slots, masks);
		NativeResultMaterializerPlan plan = new NativeResultMaterializerPlan(layout);
		CountingSource source = source(42L, 43L);
		Coordinates coordinates = new Coordinates(64);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(100_000L, 100_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			try (NativeResultMaterializer materializer = plan.open(ledger)) {
				assertThat(materializer.alias(64)).isZero();
				assertThat(materializer.begin(source, null)).isNotNull();
				long ordinaryBytes = materializer.retainedBytes();
				List<NativeProjectedBindingSet> retained = new ArrayList<>();
				for (long id : new long[] { 42L, 43L, 42L }) {
					long[] row = new long[64];
					Arrays.fill(row, NativeLmdbQuerySource.UNKNOWN_ID);
					row[0] = id;
					long[] positions = new long[64];
					positions[0] = id - 42L;
					retained.add(capture(source, layout, materializer, coordinates, row, positions));
				}
				assertThat(source.calls).containsExactly(42L, 43L, 42L);
				assertThat(retained.get(2).getValue("value64")).isSameAs(retained.get(0).getValue("value0"));
				assertThat(materializer.retainedBytes()).isEqualTo(ordinaryBytes);
				assertThat(ledger.usedBytes()).isEqualTo(ordinaryBytes);
			}
			assertThat(ledger.usedBytes()).isZero();
		}
		assertThat(manager.usedBytes()).isZero();
	}

	private static NativeProjectedBindingSet.ProjectionLayout aliasLayout() {
		return NativeProjectedBindingSet.ProjectionLayout.create(new String[] { "left", "leftAlias", "right" },
				new int[] { 0, 0, 1 }, new int[] { ValuePosition.OBJECT, ValuePosition.OBJECT, ValuePosition.OBJECT });
	}

	private static NativeProjectedBindingSet.ProjectionLayout layout(String... names) {
		int[] slots = new int[names.length];
		int[] masks = new int[names.length];
		for (int index = 0; index < names.length; index++) {
			slots[index] = index;
			masks[index] = ValuePosition.OBJECT;
		}
		return NativeProjectedBindingSet.ProjectionLayout.create(names, slots, masks);
	}

	private static CountingSource source(long... ids) {
		CountingSource source = new CountingSource();
		for (long id : ids) {
			source.values.put(id, VF.createBNode("value-" + id));
		}
		return source;
	}

	private static NativeProjectedBindingSet prepare(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			Coordinates coordinates, long[] row, long... positions) {
		coordinates.positions = positions;
		NativeProjectedBindingSet result = new NativeProjectedBindingSet(source, layout, row, materializer);
		result.setCoordinateSequence(materializer.position(coordinates, row));
		return result;
	}

	private static NativeProjectedBindingSet capture(CountingSource source,
			NativeProjectedBindingSet.ProjectionLayout layout, NativeResultMaterializer materializer,
			Coordinates coordinates, long[] row, long... positions) {
		NativeProjectedBindingSet result = prepare(source, layout, materializer, coordinates, row, positions);
		result.captureForOutput(null);
		result.detachAfterMaterialization();
		return result;
	}

	private static final class Coordinates implements NativeResultCoordinates {
		private long[] positions;

		private Coordinates(int width) {
			positions = new long[width];
		}

		@Override
		public long coordinateActivation() {
			return 1L;
		}

		@Override
		public boolean resultCoordinate(int slot, long[] coordinate) {
			if (slot < 0 || slot >= positions.length) {
				return false;
			}
			coordinate[GROUP] = 1L;
			coordinate[PARENT] = 2L;
			coordinate[POSITION] = positions[slot];
			coordinate[COLUMN] = slot;
			coordinate[NAMESPACE] = 1L;
			return true;
		}
	}

	private static final class CountingSource implements NativeLmdbQuerySource {
		private final Map<Long, Value> values = new HashMap<>();
		private final List<Long> calls = new ArrayList<>();
		private Object scope = new Object();
		private boolean closed;

		void close() {
			closed = true;
			values.clear();
		}

		@Override
		public Object resultValueScope() {
			if (closed) {
				throw new AssertionError("Closed source scope must not be consulted by retained rows");
			}
			return scope;
		}

		@Override
		public long idOf(Value value) {
			throw new UnsupportedOperationException();
		}

		@Override
		public Value lazyValue(long id) {
			return lazyValue(id, ValuePosition.NONE);
		}

		@Override
		public Value lazyValue(long id, int positionMask) {
			if (closed) {
				throw new AssertionError("Closed source must not be consulted by retained rows");
			}
			calls.add(id);
			Value result = values.get(id);
			if (result == null) {
				throw new AssertionError("Unexpected test lookup " + id);
			}
			return result;
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public long count(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean has(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public double estimate(long subject, long predicate, long object, long context) {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}
	}
